"use client";

import React, { useState } from "react";
// import { createAppointment } from "@/app/actions/bookAppointment"; // Import Action
import { useRouter } from "next/navigation";

const consultation = () => {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedSlot, setSelectedSlot] = useState("");
  const [mode, setMode] = useState("Virtual");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const formData = new FormData();
    formData.append("date", selectedDate);
    formData.append("slot", selectedSlot);
    formData.append("mode", mode);

    const result = await createAppointment(formData);

    if (result.success) {
      // Show high-tech success toast or redirect
      router.push("/appointments/success");
    } else {
      alert(result.error);
    }
    setLoading(false);
  };

  return (
    // ... Inside your existing JSX ...
    <form onSubmit={handleSubmit} className="space-y-8">
      {/* ... Date and Slot inputs stay same, just ensure they update state ... */}

      {/* Mode selection (Updated to set state) */}
      <div className="flex gap-4">
        <label className="flex-1 cursor-pointer" onClick={() => setMode("Virtual")}>
          <input type="radio" name="mode" className="hidden peer" defaultChecked />
          <div className="p-4 bg-white/5 border border-white/10 rounded-2xl peer-checked:border-teal-500 transition-all">
             {/* ... icon and text ... */}
          </div>
        </label>
        {/* repeat for In-Person */}
      </div>

      <button 
        type="submit"
        disabled={!selectedDate || !selectedSlot || loading}
        className="w-full bg-blue-600 disabled:opacity-50 ..."
      >
        {loading ? (
          <span className="flex items-center justify-center gap-2">
            <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
            Syncing...
          </span>
        ) : "Confirm Appointment"}
      </button>
    </form>
  );
};
export default consultation